DO $$
DECLARE actor uuid; org bigint; un bigint; oc bigint; form_id bigint; result jsonb; cmd uuid; baseline jsonb; start_at timestamptz:=now(); end_at timestamptz:=now()+interval '1 day';
BEGIN
 PERFORM public.create_user_for_test('config-versions','config-versions@example.invalid');actor:=public.get_user_id('config-versions');
 INSERT INTO public.organizations(title) VALUES('Configuration versions') RETURNING id INTO org;
 UPDATE public.user_info SET organization=org WHERE id=actor;
 INSERT INTO public.units(title,organization) VALUES('Configuration versions',org) RETURNING id INTO un;
 INSERT INTO public.occasions(title,organization,unit,link,start_time,end_time,data,services) VALUES('Configuration versions',org,un,gen_random_uuid()::text,start_at,end_at,'{"unrelated":true}','{}') RETURNING id INTO oc;
 INSERT INTO public.unit_users(unit,"user",is_editor,is_manager) VALUES(un,actor,true,true);
 INSERT INTO public.occasion_users(occasion,"user",is_editor_order,is_editor_order_view,is_editor,is_manager) VALUES(oc,actor,true,true,true,true);
 PERFORM set_config('request.jwt.claim.sub',actor::text,true);PERFORM set_config('request.jwt.claim.role','authenticated',true);
 baseline:=jsonb_build_object('id',oc,'title','Stale','data','{}'::jsonb,'services','{}'::jsonb);
 cmd:=gen_random_uuid();EXECUTE 'SET LOCAL ROLE authenticated';
 result:=public.create_service_item_client_sync_v1(oc,'accommodation','A','Room',NULL,cmd);ASSERT result->>'status'='applied';
 ASSERT public.create_service_item_client_sync_v1(oc,'accommodation','A','Room',NULL,cmd)=result;
 ASSERT public.save_occasion_client_sync_v1(oc,gen_random_uuid(),0,baseline)->>'status'='conflict';
 ASSERT public.update_service_item_client_sync_v1(oc,'accommodation','A','Room',NULL,gen_random_uuid())->>'status'='unchanged';
 ASSERT public.update_service_item_client_sync_v1(oc,'accommodation','A','New room',NULL,gen_random_uuid())->>'status'='applied';
 ASSERT public.save_occasion_client_sync_v1(oc,gen_random_uuid(),1,baseline)->>'status'='conflict';
 ASSERT public.game_update_settings_client_sync_v1(oc,start_at,end_at,gen_random_uuid())->>'status'='applied';
 ASSERT public.game_update_settings_client_sync_v1(oc,start_at,end_at,gen_random_uuid())->>'status'='unchanged';
 ASSERT public.save_occasion_client_sync_v1(oc,gen_random_uuid(),2,baseline)->>'status'='conflict';
 EXECUTE 'RESET ROLE';
 ASSERT (SELECT version=3 FROM public.client_aggregate_versions WHERE aggregate_type='occasion' AND scope_id=oc AND aggregate_id=oc::text);
 ASSERT (SELECT data->>'unrelated'='true' FROM public.occasions WHERE id=oc);
 PERFORM public.create_service_item(oc,'food','F','Lunch',NULL);
 UPDATE public.occasion_users SET services='{"accommodation":{"A":"paid"},"food":{"F":"paid"}}' WHERE occasion=oc AND "user"=actor;
 EXECUTE 'SET LOCAL ROLE authenticated';
 ASSERT public.delete_service_item_client_sync_v1(oc,'accommodation','A',false,gen_random_uuid())->>'status'='rejected';
 result:=public.delete_service_item_client_sync_v1(oc,'accommodation','A',true,gen_random_uuid());ASSERT result->>'status'='applied';
 EXECUTE 'RESET ROLE';
 ASSERT (SELECT services->'accommodation'='[]' AND jsonb_array_length(services->'food')=1 FROM public.occasions WHERE id=oc),'last deletion preserves sibling services';
 ASSERT (SELECT services#>>'{food,F}'='paid' AND NOT (services->'accommodation') ? 'A' FROM public.occasion_users WHERE occasion=oc AND "user"=actor);
 ASSERT (SELECT version=1 FROM public.client_aggregate_versions WHERE aggregate_type='occasion_user' AND scope_id=oc AND aggregate_id=actor::text);
 EXECUTE 'SET LOCAL ROLE authenticated';
 PERFORM public.update_entity_email_banner('occasion',oc,'https://example.invalid/banner.png');
 ASSERT public.save_occasion_client_sync_v1(oc,gen_random_uuid(),5,baseline)->>'status'='conflict';
 PERFORM public.update_entity_email_banner('occasion',oc,NULL);
 PERFORM public.update_entity_email_banner('unit',un,'https://example.invalid/banner.png');
 ASSERT public.save_unit_client_sync_v1(un,gen_random_uuid(),0,jsonb_build_object('id',un,'title','Stale','data','{}'::jsonb))->>'status'='conflict';
 EXECUTE 'RESET ROLE';
 ASSERT (SELECT data->>'unrelated'='true' FROM public.occasions WHERE id=oc),'clearing a banner preserves other occasion data';
 INSERT INTO public.forms(title,occasion,link,is_open) VALUES('Scheduled form',oc,gen_random_uuid()::text,false) RETURNING id INTO form_id;
 INSERT INTO eshop.planned_changes(occasion,subject_id,change_type,new_value,change_time) VALUES(oc,form_id,'forms.is_open','true',now()-interval '1 second');
 PERFORM set_config('request.jwt.claim.role','service_role',true);PERFORM public.apply_planned_changes_client_sync_v1();PERFORM set_config('request.jwt.claim.role','authenticated',true);
 ASSERT (SELECT is_open FROM public.forms WHERE id=form_id);
 ASSERT (SELECT version=1 FROM public.client_aggregate_versions WHERE aggregate_type='form' AND scope_id=oc AND aggregate_id=form_id::text);
 ASSERT public.update_form_client_sync_v1(jsonb_build_object('id',form_id,'occasion',oc,'expected_aggregate_version',0),gen_random_uuid())->>'status'='conflict';
 ASSERT NOT has_function_privilege('authenticated','public.create_service_item_internal_v1(bigint,text,text,text,bigint)','EXECUTE');
 ASSERT NOT has_function_privilege('authenticated','public.game_update_settings_internal_v1(bigint,timestamptz,timestamptz)','EXECUTE');
END $$;
